static void touch_cb(lv_event_t *e)
{
  lv_event_code_t code = lv_event_get_code(e);
  lv_point_t      p;
  uint32_t        dt;
  int             dx;
  int             dy;

  /* 密码面板显示时, 触摸事件应交给键盘/按钮, canvas 不处理 */
  if (g_pwd_sheet && !lv_obj_has_flag(g_pwd_sheet, LV_OBJ_FLAG_HIDDEN))
    return;

  /* WiFi 选网页显示时, 触摸事件应交给列表/按钮, canvas 不处理 */
  if (g_wifi_page && !lv_obj_has_flag(g_wifi_page, LV_OBJ_FLAG_HIDDEN))
    return;

  lv_indev_get_point(lv_indev_active(), &p);

