static void close_wifi_page(void)
{
  /* 先停扫描定时器, 再等扫描线程退出, 避免竞态 */
  if (g_scan_timer != NULL)
    {
      lv_timer_del(g_scan_timer);
      g_scan_timer = NULL;
    }
  pthread_join(g_scan_tid, NULL);

  if (g_wifi_page) lv_obj_add_flag(g_wifi_page, LV_OBJ_FLAG_HIDDEN);
  if (g_pwd_sheet) lv_obj_add_flag(g_pwd_sheet, LV_OBJ_FLAG_HIDDEN);
  refresh_net_ui();
}

