def device_config_get_for_board(device_code: str) -> dict | None:
    """Board API: get config without auth."""
    dev = device_get(device_code)
    if not dev:
        return None
    return dev.get("config", {})


# ---------------------------------------------------------------------------
# Device expression & status
# ---------------------------------------------------------------------------

def device_set_expr(device_code: str, idx: int):
    """Set current expression index for a device."""
    with _lock:
        data = _load()
        dev = data["devices"].get(device_code)
        if not dev:
            return
        if "status" not in dev:
            dev["status"] = {}
        dev["status"]["expr_index"] = idx
        dev["status"]["updated_at"] = _now_iso()
        _save(data)


def device_get_status(device_code: str) -> dict | None:
    """Get device status (expression, uptime, etc.)."""
    dev = device_get(device_code)
    if not dev:
        return None
    status = dev.get("status", {})
    status["online"] = dev.get("online", False)
    status["last_seen"] = dev.get("last_seen")
    status["name"] = dev.get("name", "")
    return status


# ---------------------------------------------------------------------------
# Memory (记忆库)
# ---------------------------------------------------------------------------

def memory_list(username: str) -> list:
    """List all memories for a user."""
    with _lock:
        data = _load()
        if "memory" not in data:
            data["memory"] = {}
        user_mems = data["memory"].get(username, [])
        return user_mems


def memory_add(username: str, content: str, category: str = "手动") -> dict:
    """Add a memory entry."""
    with _lock:
        data = _load()
        if "memory" not in data:
            data["memory"] = {}
        if username not in data["memory"]:
            data["memory"][username] = []
        mem = {
            "id": secrets.token_hex(8),
            "content": content,
            "category": category,
            "created_at": _now_iso(),
        }
        data["memory"][username].append(mem)
        _save(data)
        return mem


def memory_delete(username: str, mem_id: str) -> bool:
    """Delete a memory entry."""
    with _lock:
        data = _load()
        mems = data.get("memory", {}).get(username, [])
        for i, m in enumerate(mems):
            if m.get("id") == mem_id:
                mems.pop(i)
                _save(data)
                return True
        return False


