    "system": "你是 OpenVela 智能看板小助手，运行在用户的桌面设备上。性格活泼贴心，回答保持简短。",
    "memory_filter": "从对话中提取值得长期记住的信息：日程安排、个人偏好、重要事实、设备使用习惯。",
    "memory_tidy": "审查以下记忆列表：合并语义重复的条目；已经过去且无重复规律的日程标记为过期。",
    "weather": "根据天气数据生成一句适合语音播报的提示，包含温度范围和建议。",
    "reminder": "到点播报提醒事项，先叫一声主人，再说事项。",
    "news": "为每条新闻生成一句20字内的导读，突出看点，口语化。",
}


def prompts_get(username: str) -> dict:
    """Get prompts config for a user."""
    with _lock:
        data = _load()
        if "prompts" not in data:
            data["prompts"] = {}
        return data["prompts"].get(username, DEFAULT_PROMPTS.copy())


def prompts_set(username: str, prompts: dict):
    """Save prompts config for a user."""
    with _lock:
        data = _load()
        if "prompts" not in data:
            data["prompts"] = {}
        if username not in data["prompts"]:
            data["prompts"][username] = DEFAULT_PROMPTS.copy()
        data["prompts"][username].update(prompts)
        _save(data)


