static void backend_poll_cb(lv_timer_t *t)
{
  LV_UNUSED(t);
  if (!net_connected()) return;

  char cmd[256];
  snprintf(cmd, sizeof(cmd),
           "curl -s -m 5 http://%s:%d/api/device/%s/status > /tmp/eye_status.json 2>/dev/null",
           SERVER_HOST, SERVER_PORT, g_device_code);
  system(cmd);

  FILE *fp = fopen("/tmp/eye_status.json", "r");
  if (!fp) return;

  char buf[512] = "";
  size_t n = fread(buf, 1, sizeof(buf) - 1, fp);
  fclose(fp);
  buf[n] = '\0';

  /* 简单解析 expr_index */
  char *p = strstr(buf, "\"expr_index\"");
  if (p)
    {
      p = strchr(p, ':');
      if (p)
        {
          p++;
          while (*p == ' ') p++;
          int idx = atoi(p);
          if (idx >= 0 && idx < EX_N && idx != g_expr)
            {
              g_remote_expr = idx;
              printf("[eye] Remote expr: %d (%s)\n", idx, EXPRS[idx].name);
            }
        }
    }
}

/* 启动时拉取后端配置 */
static void pull_backend_config(void)
{
  if (!net_connected()) return;

  char cmd[256];
  snprintf(cmd, sizeof(cmd),
           "curl -s -m 5 http://%s:%d/api/device/%s/config > /tmp/eye_cfg.json 2>/dev/null",
           SERVER_HOST, SERVER_PORT, g_device_code);
