  fclose(fp);
  buf[n] = '\0';

  printf("[eye] Backend config: %s\n", buf);

  /* 解析 default_expr */
  char *p = strstr(buf, "\"default_expr\"");
  if (p)
    {
      p = strchr(p, ':');
      if (p)
        {
          p++;
          while (*p == ' ' || *p == '"') p++;
          /* 找匹配的表情名 */
          for (int i = 0; i < EX_N; i++)
            {
              if (strncmp(p, EXPRS[i].name, strlen(EXPRS[i].name)) == 0)
                {
                  set_expr(i);
