@app.route("/api/chat", methods=["POST"])
@login_required
def api_chat(user):
    """Web 端发消息, 后端调 MiMo LLM 返回回复."""
    body = _json_body()
    message = body.get("message", "")
    device_code = body.get("device_code", "")
    if not message:
        return jsonify({"error": "message required"}), 400

    if not MIMO_API_KEY:
        return jsonify({"ok": True, "reply": "LLM 未配置 (请设置 MIMO_API_KEY 环境变量)", "action": None})

    try:
        import urllib.request
        import urllib.error

        # 读取用户提示词配置
        prompts = store.prompts_get(user["username"])
        system_prompt = prompts.get("system", "你是智能看板助手，回答简短。")

        req_body = json_mod.dumps({
            "model": MIMO_MODEL,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": message}
            ],
            "max_tokens": 500
        }).encode("utf-8")

        req = urllib.request.Request(
            MIMO_BASE_URL + "/chat/completions",
            data=req_body,
            headers={
                "Authorization": "Bearer " + MIMO_API_KEY,
                "Content-Type": "application/json"
            }
        )

        with urllib.request.urlopen(req, timeout=30) as resp:
            result = json_mod.loads(resp.read().decode("utf-8"))
            reply = result.get("choices", [{}])[0].get("message", {}).get("content", "")
            if not reply:
                reply = "(模型返回为空)"

            # 简单意图识别: 如果回复包含表情关键词, 设置 action
            action = None
            expr_keywords = {
                "开心": "happy", "大笑": "laugh", "难过": "sad",
                "生气": "angry", "惊讶": "surprised", "思考": "thinking",
                "困倦": "sleepy", "睡觉": "sleep"
            }
            for kw, act in expr_keywords.items():
                if kw in message or kw in reply:
                    action = act
                    break

            return jsonify({"ok": True, "reply": reply, "action": action})

    except Exception as e:
        return jsonify({"ok": True, "reply": f"LLM 调用失败: {str(e)}", "action": None})

