/* ======== 语音录音 ======== */
var g_media_recorder=null;
var g_audio_chunks=[];
var g_recording=false;

async function toggleMic(){
  if(g_recording){stopMic();return;}
  try{
    var stream=await navigator.mediaDevices.getUserMedia({audio:true});
    g_media_recorder=new MediaRecorder(stream);
    g_audio_chunks=[];
    g_media_recorder.ondataavailable=function(e){g_audio_chunks.push(e.data);};
    g_media_recorder.onstop=function(){
      stream.getTracks().forEach(function(t){t.stop();});
      var blob=new Blob(g_audio_chunks,{type:'audio/wav'});
      sendVoice(blob);
    };
    g_media_recorder.start();
    g_recording=true;
    document.getElementById('micBtn').textContent='⏹ 停止';
    document.getElementById('micBtn').style.background='#fef2f2';
    document.getElementById('micBtn').style.color='#dc2626';
    document.getElementById('voiceStatus').textContent='录音中...';
  }catch(e){
    toast('无法访问麦克风: '+e.message);
  }
}

function stopMic(){
  if(g_media_recorder&&g_recording){
    g_media_recorder.stop();
    g_recording=false;
    document.getElementById('micBtn').textContent='🎤 录音';
    document.getElementById('micBtn').style.background='#f0fdf4';
    document.getElementById('micBtn').style.color='#16a34a';
    document.getElementById('voiceStatus').textContent='识别中...';
  }
}

async function sendVoice(blob){
  if(!g_cur_dev){toast('请先绑定设备');return;}
  var r=await fetch('/api/device/'+g_cur_dev+'/voice',{
    method:'POST',
    headers:{'Authorization':'Bearer '+T},
    body:blob
  });
  var j=await r.json();
  if(j.ok){
    if(j.user_text) addChatMsg(j.user_text,'user');
    if(j.text) addChatMsg(j.text,'bot');
    if(j.audio){
      var audio=new Audio('data:audio/wav;base64,'+j.audio);
      audio.play();
    }
    if(j.action) setExprByName(j.action);
    document.getElementById('voiceStatus').textContent='';
  }else{
    document.getElementById('voiceStatus').textContent='语音失败: '+(j.error||'');
  }
}

