async function sendVoice(blob){
  if(!g_cur_dev){toast('请先绑定设备');return;}
  var r=await fetch('/api/device/'+g_cur_dev+'/voice',{
    method:'POST',
    headers:{'Authorization':'Bearer '+T},
    body:blob
  });
  var j=await r.json();
  if(j.ok){
    if(j.user_text) addChatMsg(j.user_text,'user');
    if(j.text) addChatMsg(j.text,'bot');
    if(j.audio){
      var audio=new Audio('data:audio/wav;base64,'+j.audio);
      audio.play();
    }
    if(j.action) setExprByName(j.action);
    document.getElementById('voiceStatus').textContent='';
  }else{
    document.getElementById('voiceStatus').textContent='语音失败: '+(j.error||'');
  }
}

