@login_required
def api_chat(user):
    """Web 端发消息, 后端调 MiMo LLM 返回回复 + 表情."""
    body = _json_body()
    message = body.get("message", "")
    device_code = body.get("device_code", "")
    if not message:
        return jsonify({"error": "message required"}), 400

    if not MIMO_API_KEY:
        return jsonify({"ok": True, "reply": "LLM 未配置", "action": None, "expr_index": 0})

    try:
        import urllib.request

        # 读取用户提示词配置
        prompts = store.prompts_get(user["username"])
        system_prompt = prompts.get("system", store.DEFAULT_PROMPTS["system"])

        req_body = json_mod.dumps({
            "model": MIMO_MODEL,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": message}
            ],
            "tools": store.EXPRESSION_TOOLS,
            "tool_choice": "auto",
            "max_tokens": 500
        }).encode("utf-8")

        req = urllib.request.Request(
            MIMO_BASE_URL + "/chat/completions",
            data=req_body,
            headers={
                "Authorization": "Bearer " + MIMO_API_KEY,
                "Content-Type": "application/json"
            }
        )

        with urllib.request.urlopen(req, timeout=30) as resp:
            result = json_mod.loads(resp.read().decode("utf-8"))
            msg = result.get("choices", [{}])[0].get("message", {})
            reply = msg.get("content", "")
            if not reply:
                reply = "(模型返回为空)"

            # 解析 function call → 表情
            expr_index = 0
            tool_calls = msg.get("tool_calls", [])
            if tool_calls:
                for tc in tool_calls:
                    fn = tc.get("function", {})
                    if fn.get("name") == "set_expression":
                        try:
                            args = json_mod.loads(fn.get("arguments", "{}"))
                            expr_name = args.get("name", "平静")
                            expr_index = store.EXPR_NAME_TO_INDEX.get(expr_name, 0)
                        except Exception:
                            pass

            # 存储表情到设备状态
            if device_code:
                store.device_set_expr(device_code, expr_index)

            return jsonify({
                "ok": True,
                "reply": reply,
                "expr_index": expr_index,
                "expr_name": list(store.EXPR_NAME_TO_INDEX.keys())[expr_index]
            })

    except Exception as e:
        return jsonify({"ok": True, "reply": f"LLM 调用失败: {str(e)}", "action": None, "expr_index": 0})

